def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_values = [row[i] for row in rows]
        total = 0
        numeric_count = 0
        for val in col_values:
            try:
                num = float(val)
                total += num
                numeric_count += 1
            except (ValueError, TypeError):
                # Non-numeric, skip
                pass
        if numeric_count == 0:
            totals.append("")
        else:
            if total.is_integer():
                totals.append(int(total))
            else:
                totals.append(total)
    return totals

